def package_steps(request):
    param = request.param
    package = Package()
    package.status = package.OK
    package.desc_status = ''
    print('\n###############################################################################')
    print('\nCaso de Prueba: ')
    print('\nINPUT MESSAGE\n', param)
    package.message_in.body = [param]

    return package

def test_steps(package_steps):
    TRACE_STEP = TraceStep(name='test_trace_step')
    package_1 = TRACE_STEP(package_steps)

    VALIDATION_STEP = ValidationStep(name='test_validation_step', filters=PARAMETERS['FILTERS'])
    package_2 = VALIDATION_STEP(package_1)

    TRANSFORMATION_STEP = TransformationStep(name='test_transformation_step')
    package_3 = TRANSFORMATION_STEP(package_2)

    if package_3.status == Package.OK:
        print('\nOUTPUT OK MESSAGE BODY\n', package_3.message_in.body)
        print('\nOUTPUT OK MESSAGE DESCRIPTION\n', package_3.desc_status)
        print('\nOUTPUT OK MESSAGE HEADER\n', package_3.message_in.header)
        print('\n###############################################################################\n')
        assert package_3.status == Package.OK
    else:
        print('\nOUTPUT ERROR MESSAGE BODY\n', package_3.message_in.body)
        print('\nOUTPUT ERROR MESSAGE DESCRIPTION\n', package_3.desc_status)
        print('\nOUTPUT ERROR MESSAGE HEADER\n', package_3.message_in.header)
        print('\n###############################################################################\n')
        assert package_3.status == Package.ERROR
